using Mutagen.Bethesda.Plugins.Binary.Headers;
using Mutagen.Bethesda.Plugins.Meta;
using Mutagen.Bethesda.Starfield;
using Shouldly;
using Xunit;
using static Mutagen.Bethesda.UnitTests.Plugins.Records.Starfield.StarfieldTestRecords;

namespace Mutagen.Bethesda.UnitTests.Plugins.Records.Starfield;

// Npc fields get xEdit's names (RegisterRecordDef(NPC_)):
// - AIDT's last byte is the Bool HasReactionRadiusBehavior (7,131 AIDT: 5,484 x 0, 1,647 x 1; the 1,647 are exactly
//   the NPCs with an RDSA), and RDSAs becomes ReactionRadiusBehaviors.
// - FLEE becomes FleeSettings: three global links and the floats Flee Distance, Safe Timer and Chance of Diversion
//   Animation. The last was read as an Int32 (it is 0 in all 30 FLEE of Starfield.esm, so no value changes).
// - TPTA entries 14 and 15 are ReactionRadiusTemplate and CombatStyleTemplate (2,528 and 3,759 records hold links).
// Each test reads a whole NPC from Starfield.esm (FULL left out: it is a localized string ID) with both readers and
// writes it back byte for byte.
public class NpcFieldNameTests
{
    private static IEnumerable<INpcGetter> Read(string hex)
        => ReadBoth<INpcGetter>(Record("NPC_", Hex(hex)), f => Npc.CreateFromBinary(f), (s, p) => NpcBinaryOverlay.NpcFactory(s, p));

    private static void WritesBack(INpcGetter npc, string hex)
    {
        var written = GameConstants.Starfield.MajorRecord(Write(w => npc.WriteToBinary(w)));
        written.Content.ToArray().ShouldBe(Hex(hex));
    }

    // LvlTurretShort_CrimsonFleet (0028DD:Starfield.esm)
    private const string Turret = "";

    // HT_GenericCitizen_F01 (2A80E7:Starfield.esm)
    private const string Citizen = "";

    // LC107_Crew_Liang_Corpse (001E3D:Starfield.esm)
    private const string Corpse = "";

    [Fact]
    public void Turret_ReactionRadiusBehavior()
    {
        foreach (var npc in Read(Turret))
        {
            npc.HasReactionRadiusBehavior.ShouldBeTrue();
            npc.ReactionRadiusBehaviors.ShouldHaveSingleItem();
            WritesBack(npc, Turret);
        }
    }

    [Fact]
    public void Citizen_FleeSettings()
    {
        foreach (var npc in Read(Citizen))
        {
            npc.HasReactionRadiusBehavior.ShouldBeFalse();
            var flee = npc.FleeSettings.ShouldNotBeNull();
            flee.FleeDistanceGlobal.IsNull.ShouldBeTrue();
            flee.SafeTimerGlobal.IsNull.ShouldBeTrue();
            flee.ChanceOfDiversionAnimationGlobal.IsNull.ShouldBeTrue();
            flee.FleeDistance.ShouldBe(10f);
            flee.SafeTimer.ShouldBe(30f);
            flee.ChanceOfDiversionAnimation.ShouldBe(0f);
            WritesBack(npc, Citizen);
        }
    }

    [Fact]
    public void Corpse_TemplateActors()
    {
        foreach (var npc in Read(Corpse))
        {
            var tpta = npc.TemplateActors.ShouldNotBeNull();
            // LC107_Crew_Template_Corpse (040F46:Starfield.esm)
            tpta.ReactionRadiusTemplate.FormKey.ID.ShouldBe(0x040F46u);
            tpta.CombatStyleTemplate.FormKey.ID.ShouldBe(0x040F46u);
            WritesBack(npc, Corpse);
        }
    }
}
